"use client";
import {useState} from "react"; import {createSupabaseBrowserClient} from "../../lib/supabase";
export default function AuthPage(){const[email,setEmail]=useState("");const[sent,setSent]=useState(false);const[error,setError]=useState("");async function signIn(){setError("");const supabase=createSupabaseBrowserClient();if(!supabase){setError("Supabase is not configured yet.");return;}const{error}=await supabase.auth.signInWithOtp({email,options:{emailRedirectTo:window.location.origin+"/auth/callback"}});if(error)setError(error.message);else setSent(true);}return <main className="min-h-screen bg-[#09090b] p-6 text-white"><div className="mx-auto mt-24 max-w-md rounded-3xl border border-zinc-800 bg-zinc-950 p-8"><h1 className="text-2xl font-bold">Sign in to PDFMate</h1><p className="mt-2 text-sm text-zinc-500">Secure email magic-link authentication.</p><input type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@example.com" className="mt-6 w-full rounded-xl border border-zinc-800 bg-zinc-900 px-4 py-3"/><button onClick={signIn} className="mt-3 w-full rounded-xl bg-violet-500 px-4 py-3 font-semibold">Send sign-in link</button>{sent&&<p className="mt-4 text-sm text-emerald-400">Check your email.</p>}{error&&<p className="mt-4 text-sm text-red-400">{error}</p>}</div></main>}
